@'
import {readFileSync,readdirSync,statSync,existsSync} from 'node:fs';
import {resolve,dirname} from 'node:path';
import {createHash} from 'node:crypto';
import {parse} from 'yaml';
const root='skills/spring-boot';
const artifacts='C:/Users/robso/AppData/Local/Temp/skills-wave2-validation-Bu1zNV/spring-boot-check';
const walk=p=>readdirSync(p).flatMap(n=>{const path=p+'/'+n;return statSync(path).isDirectory()?walk(path):[path]});
const sha=p=>createHash('sha256').update(readFileSync(p)).digest('hex');
const files=walk(root);
const doc=readFileSync(root+'/SKILL.md','utf8');
const manifest=parse(readFileSync(root+'/skill.yaml','utf8'));
const front=parse(doc.split('---')[1]);
const links=[];
for(const file of files.filter(f=>f.endsWith('.md'))){
  const content=readFileSync(file,'utf8');
  for(const match of content.matchAll(/\[[^\]]*\]\((?:<([^>]+)>|([^\s)]+))\)/g)){
    const href=match[1]??match[2];
    if(/^(?:https?:|mailto:|#)/.test(href)) continue;
    const target=resolve(dirname(file),decodeURIComponent(href.split('#')[0]));
    links.push({file,href,exists:existsSync(target)});
  }
}
const issues=[];
if(front.name!==manifest.name) issues.push('name mismatch');
if(front.description!==manifest.description) issues.push('description mismatch');
if(manifest.version!=='1.2.2') issues.push('unexpected version');
for(const link of links) if(!link.exists) issues.push('missing '+link.file+' -> '+link.href);
console.log(JSON.stringify({
  version:manifest.version,name:manifest.name,descriptionMatches:front.description===manifest.description,
  files:files.map(path=>({path,sha256:sha(path)})),
  artifacts:walk(artifacts).map(path=>({path,sha256:sha(path)})),
  localLinks:links,issues
},null,2));
if(issues.length) process.exitCode=1;
'@ | node --input-type=module

